return {
  [ [[v5748eaic9o9g]] ] = { t = [[完美打击与徒手打击]], q = [[我能用徒手打击来使用这个专长吗？]], a = [=[按现有文字，你只能把这个专长用于专长描述里列出的那几种武器。

那为什么专长要求[[精通徒手打击]]作先决条件，却又不能用于徒手打击呢？因为这个专长本意是给[[武僧]]一件很酷的事情去做，而武僧会自动获得精通徒手打击（除非某个变体职业替换掉了这个专长），所以把它设成先决条件，武僧就很容易学到完美打击，其他职业则比较困难。先决条件本来也可以写成“武僧等级X”，但那样就只有武僧能选这个专长了（连其他武术类职业或变体职业也不行）。

注意，[[禅宗射手]]变体职业允许你把这个专长用于弓，这说明已有先例：可以设计一个徒手战斗的变体职业，修改这个专长使其适用于其他武器。]=], book = [[进阶玩家指南]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9o9g]], cat = [[FAQ]], ai = false, pages = { [[完美打击]] } },
  [ [[v5748eaic9rce]] ] = { t = [[异界生物子域与异界誓缚]], q = [[牧师，异界生物子域：这些子域赋予的异界誓缚领域法术，我该怎么用？]], a = [=[这是一处错误：异界生物子域的阵营，与束缚相应类型的异界生物所需的反阵营法阵（magic circle）法术，存在阵营冲突。例如，拥有幻蛇（混乱）子域的混乱阵营牧师，要束缚一只混乱的幻蛇，就得施展一个[秩序]的[[反混乱法阵]]领域法术，但她的混乱阵营使她无法这么做（见《核心规则书》中的“混乱、邪恶、善良和秩序法术”）。

解决办法是：允许这个异界誓缚领域法术在使用时不需要施展反阵营法阵。（如果牧师想绘制一张呼唤图阵来提高成功率，可以请另一名施法者来施展所需的反阵营法阵。）

这段文字将在《进阶玩家指南》的下次印刷中更新。]=], book = [[进阶玩家指南]], date = [[2013/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9rce]], cat = [[FAQ]], ai = false, pages = { [[异界誓缚]], [[领域]] } },
  [ [[v5748eaic9pka]] ] = { t = [[远古血脉与种族变体职业]], q = [[拥有这个专长的人类，能兼任要求特定种族的变体职业吗？]], a = [[可以。远古血脉专长让你能够满足以所选种族为要求的变体职业的资格，前提是你仍然满足兼任该变体职业的其他所有要求。]], book = [[进阶玩家指南]], date = [[2012/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9pka]], cat = [[FAQ]], ai = false, pages = { [[远古血脉]] } },
  [ [[v5748eaic9ni6]] ] = { t = [[狂野预知不能叠等级]], q = [[怒火先知的狂野预知能力，能让他把野蛮人或先知等级与怒火先知等级叠加，以满足狂暴之力和秘示域的要求吗？]], a = [[不能。]], book = [[进阶玩家指南]], date = [[2010/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ni6]], cat = [[FAQ]], ai = false, pages = { [[怒火先知]] } },
  [ [[v5748eaic9qjz]] ] = { t = [[触及进化的攻击次数]], q = [[如果我给幻灵选了触及进化，它有几次攻击能获得更远的触及？]], a = [[该能力描述写的是“选择一项攻击”，而不是“选择一种攻击类型”。所以如果你的幻灵有两只爪抓，而你为触及进化选了“爪抓”，那么只有一只爪抓获得更远的触及。（触及进化的本意是让你能模拟出龙形的幻灵，因为龙的啮咬攻击比爪抓触及更远。）]], book = [[进阶玩家指南]], date = [[2013/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9qjz]], cat = [[FAQ]], ai = false, pages = { [[幻灵]] } },
  [ [[v5748eaic9ofz]] ] = { t = [[先知的正气如虹与伤害减免]], q = [=[先知施展[[正气如虹]]时，会获得哪种伤害减免？]=], a = [[如果先知为已知法术选择了“所有治疗法术”的选项，就视同“能引导正能量”来处理正气如虹；如果她选择的是“所有造成伤害法术”，就视同“能引导负能量”来处理。]], book = [[进阶玩家指南]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ofz]], cat = [[FAQ]], ai = false, pages = { [[正气如虹]], [[先知]] } },
  [ [[v5748eaic9n9z]] ] = { t = [[神圣使徒的领域益处]], q = [[圣武士：神圣使徒变体职业（第117页）获得一个领域。神圣使徒能得到该领域的全部益处，比如神授力量吗？]], a = [[可以。除非文字明确另有说明，否则角色获得牧师领域时，就获得与该领域相关的全部益处：神授力量、领域法术的使用权，以及每个她能施展的法术环级上的一个领域法术位。]], book = [[进阶玩家指南]], date = [[2010/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9n9z]], cat = [[FAQ]], ai = false, pages = { [[神圣使徒]] } },
  [ [[v5748eaic9nd9]] ] = { t = [[其他职业的子域]], q = [[德鲁伊、审判者以及其他能获得领域的职业，可以选择《进阶玩家指南》牧师部分列出的子域吗？]], a = [[可以，只要遵守第86页的子域规则。不信奉神祇的角色（比如某些德鲁伊和圣武士）可以选择其职业可用的任一领域所对应的任一子域。]], book = [[进阶玩家指南]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9nd9]], cat = [[FAQ]], ai = false, pages = { [[领域]], [[审判者]] } },
  [ [[v5748eaic9ncx]] ] = { t = [[甄选法术的本意]], q = [=[按字面所写，这个专长使你能有选择地让某些目标不受[[黑触手]]和[[反魔场]]之类法术的影响。这是该专长的本意吗？]=], a = [[不是，它只影响持续时间为立即的法术。《进阶玩家指南》勘误会对此加以澄清。（SKR，2010年10月8日）]], book = [[进阶玩家指南]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ncx]], cat = [[FAQ]], ai = false, pages = { [[甄选法术]] } },
  [ [[v5748eaic9qpq]] ] = { t = [[次等灵魂图腾的攻击与效果]], q = [[野蛮人，次等灵魂图腾：灵魂攻击谁由谁决定？哪些效果会影响这些灵魂？]], a = [=[野蛮人每轮决定灵魂攻击谁。灵魂不受那些协助其攻击或伤害的效果（如[[吟游表演]]或[[祝福术]]）影响，也不受那些削弱其攻击或伤害的效果（如[[绝望术]]或[[黑暗术]]）影响。灵魂总是从你的方向发起攻击，它们不会获得夹击加值，也不能帮助任何战斗者取得夹击。]=], book = [[进阶玩家指南]], date = [[2013/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9qpq]], cat = [[FAQ]], ai = false, pages = { [[次等灵魂图腾]] } },
  [ [[v5748eaic9pkb]] ] = { t = [[进阶玩家指南的法杖价格]], q = [[《进阶玩家指南》魔法物品一节里的法杖，价格似乎只有正常的一半，这是对的吗？]], a = [[不对。《进阶玩家指南》里的法杖价格有误，应为所列价格的两倍。这些法杖已在《极限宝具》中以正确价格重印。]], book = [[进阶玩家指南]], date = [[2012/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9pkb]], cat = [[FAQ]], ai = false, pages = { [[魔法物品/法杖]] } },
  [ [[v5748eaic9ni4]] ] = { t = [[生命羁绊何时触发]], q = [[召唤师：召唤师的生命羁绊（第57页）如何运作？召唤师昏迷时幻灵就会消失，所以这个能力几乎不可能触发。]], a = [[这个能力应当在对召唤师造成的伤害会使他降到0生命值以下时触发，而不只是在伤害会杀死他时。（《进阶玩家指南》第二次印刷已包含这条更新。）]], book = [[进阶玩家指南]], date = [[2010/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ni4]], cat = [[FAQ]], ai = false, pages = { [[召唤师]] } },
  [ [[v5748eaic9oh2]] ] = { t = [[重新召唤幻灵时的生命值]], q = [[召唤师：我重新召唤被放逐或遣返的幻灵时，它出现时有多少生命值？]], a = [[幻灵被遣返或放逐（而不是被杀死）时有多少生命值，再次被召唤时就有多少生命值。

更新：《进阶玩家指南》第55页，幻灵描述，第2段第2句，将“与上一次被召唤时相同”改为“与上一次被遣返或放逐时相同”。]], book = [[进阶玩家指南]], date = [[2011/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9oh2]], cat = [[FAQ]], ai = false, pages = { [[召唤师]] } },
  [ [[v5748eaic9oh4]] ] = { t = [[生命连结不占动作]], q = [[召唤师：不是我的回合、我被麻痹或者无法行动时，我还能使用生命连结吗？]], a = [=[尽管这个能力被列为自由动作，但只要幻灵将受到足以把它送回原属位面的伤害，召唤师就应该能随时使用它，即使不在他的回合（他遭到攻击时通常就是这样）、因力量或敏捷毒素而无助、被[[人类定身术]]定身，等等。换言之，它根本不是一个动作，也不该被列为动作。

更新：《进阶玩家指南》第56页，生命连结描述，第1段第2句，删去“用一个自由动作”。]=], book = [[进阶玩家指南]], date = [[2011/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9oh4]], cat = [[FAQ]], ai = false, pages = { [[召唤师]] } },
  [ [[v5748eaic9qdg]] ] = { t = [[图腾战士与图腾狂暴之力]], q = [[野蛮人，图腾战士：这个变体职业允许我选取不止一类图腾狂暴之力吗？]], a = [[不能，《极限战斗》里的那一句有误；野蛮人不能从多于一组的图腾狂暴之力中选择。

