  [ [[v5748eaic9ne4]] ] = { t = [[圣光斗士的光环]], q = [[圣武士：圣光斗士变体职业（第118页）的“光环”能力，在对抗黑暗效果时算哪种光？圣武士激活这个能力有次数限制吗？12级的能力是只影响圣武士的盟友，还是也影响圣武士本人？]], a = [[这个能力直到8级为止算作光亮，到了8级则算作日光。激活光环会消耗一次她的圣疗使用次数。光环的所有效果既作用于盟友，也作用于圣武士本人（游戏规则视你为自己的盟友）。

《进阶玩家指南》的更新将包含这些澄清。]], book = [[进阶玩家指南]], date = [[2010/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ne4]], cat = [[FAQ]], ai = true, pages = { [[圣光斗士]] } },
  [ [[v5748eaic9r9k]] ] = { t = [[武器链的动作类型]], q = [[用武器链取回系在手腕上的武器，是什么动作？]], a = [=[最初出版时，这是一个[[迅捷动作]]。设计团队已将它改为[[移动动作]]，将在《进阶玩家指南》的下次印刷中更新。]=], book = [[进阶玩家指南]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9r9k]], cat = [[FAQ]], ai = false, pages = { [[武器链]] } },
  [ [[v5748eaic9nii]] ] = { t = [[进阶职业与庇护主法术]], q = [=[女巫：如果我兼任一个能提升施法能力的[[进阶职业]]，升级时还会继续从庇护主那里获得额外法术吗？]=], a = [[不会。那是女巫职业的职业特性，而标准的“+1级施法”进阶职业能力只提升已知法术、每日法术数量和有效施法者等级。（当然，你从魔宠那里获得的庇护主法术，仍按你实际的女巫等级计算。）]], book = [[进阶玩家指南]], date = [[2010/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9nii]], cat = [[FAQ]], ai = false, pages = { [[女巫]] } },
  [ [[v5748eaic9ot2]] ] = { t = [[24小时限制与其他女巫]], q = [[女巫：如果一项巫术说每24小时只能影响同一个生物一次，是否意味着其他女巫也不能对该目标使用这项巫术？]], a = [[不是。这个限制只针对使用该巫术的那一名女巫，并不妨碍其他女巫对目标使用她们自己的同名巫术。

例如，如果艾斯梅拉达对古斯塔夫使用了她的治愈巫术，她在24小时内就不能再对他使用。莫尔达仍然可以在艾斯梅拉达的“治愈巫术禁用期”内对古斯塔夫使用自己的治愈巫术（这样做之后，莫尔达也在24小时内不能再对他使用）。其他任何使用治愈巫术的女巫依此类推，无穷无尽。]], book = [[进阶玩家指南]], date = [[2011/01/12]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9ot2]], cat = [[FAQ]], ai = false, pages = { [[女巫]] } },
